OA3 = "LE06 OA 03"

FAB = "Un gallo orgulloso se subió al tejado y gritó: «¡Yo hago salir el sol! Todos los días canto y el sol aparece». Un día el gallo se enfermó y no pudo cantar, pero el sol salió igual. El gallo bajó del tejado en silencio. Moraleja: no te creas dueño de lo que no depende de ti."
LEY = "Dicen en el pueblo imaginario de Calderilla que la laguna se formó con las lágrimas de una pastora que perdió su rebaño en una nevada. Por eso, cuando cae la primera nieve, los vecinos dejan un farol de colores junto a la orilla para que la pastora encuentre el camino a casa."
MITO = "Cuentan que al comienzo del mundo no había día ni noche. La Tortuga Gigante cargaba la luz en su caparazón y, cada vez que respiraba, la luz subía y bajaba. Así nacieron el día y la noche."
FOLK = "Había una vez una anciana que tenía una olla de barro que nunca se vaciaba. Cada vez que alguien tenía hambre, la olla se llenaba de sopa. Pero la olla solo daba sopa si la anciana la compartía; el día que quiso guardarla para ella sola, la olla quedó vacía para siempre."
POEMA = "El viento peina los cerros / y despeina mi flequillo; / canta bajito en los techos / y baila con mi abrigo."
HIST = "Viñeta 1: un niño mira un globo rojo que se escapa. Globo de diálogo: «¡Vuelve!». Viñeta 2: el niño corre tras el globo. Onomatopeya: ¡PAF PAF PAF! (sus zapatillas). Viñeta 3: el globo se enreda en un árbol. Globo de pensamiento: «Necesito ayuda»."
NOVELA = "Capítulo 1. La llegada. Cuando Rafaela bajó del barco, la isla ya estaba oscureciendo. Nadie la esperaba en el muelle, solo una cabra flaca que la miraba desde un montón de redes."

L(OA3, 1,
  MAT,
  "Aprenderé a reconocer los distintos géneros de la literatura y a explicar para qué sirve leerlos: conocer el mundo, imaginar y valorar nuestra cultura.",
  ["Sé qué es un cuento.", "Conozco poemas y fábulas de cursos anteriores."],
  ["La literatura reúne textos creados para emocionar, imaginar y comprender el mundo. Leer literatura nos permite conocer lugares, épocas y costumbres que no hemos vivido, desarrollar la imaginación y reconocer el valor social y cultural de las historias que una comunidad cuenta y conserva.",
   "Hay muchos géneros. El poema se escribe en versos. El cuento folclórico viene de la tradición oral y no tiene un autor conocido; el cuento de autor sí lo tiene. La fábula está protagonizada por animales y termina en una moraleja. La leyenda explica un lugar o un hecho mezclando lo real y lo fantástico. El mito explica el origen del mundo o de un fenómeno. La novela es larga y se divide en capítulos. La historieta cuenta con viñetas y globos de diálogo.",
   "Para reconocer el género, busca pistas: ¿hay versos?, ¿hay moraleja?, ¿hay viñetas?, ¿se explica el origen de algo? Descubrir el género te ayuda a saber qué esperar del texto y cómo leerlo. Ese es el primer desafío de este tema."],
  [("género literario", "tipo de texto literario, como poema, fábula o novela"), ("tradición oral", "historias que se cuentan de boca en boca por generaciones"), ("moraleja", "enseñanza que deja una fábula"), ("viñeta", "cuadro de una historieta")],
  [("Reconocer una leyenda", f"Lee: «{LEY}» ¿De qué género es y qué pista lo muestra?",
    ["Busco si explica el origen de un lugar: la laguna.", "Veo que mezcla algo posible (una nevada) con algo fantástico (la laguna nace de lágrimas).", "Eso es propio de una leyenda."],
    "Es una leyenda: explica un lugar mezclando lo real y lo fantástico"),
   ("Reconocer una historieta", "Un texto dice: «Viñeta 1: una niña salta. Globo de diálogo: ¡Allá voy!». ¿Qué género es?",
    ["Veo la palabra viñeta.", "Veo un globo de diálogo.", "Son rasgos de una historieta."],
    "Es una historieta")],
  [("Decir que todo texto que tiene un animal es una fábula.", "Se mira solo a los personajes.", "Busca también la moraleja y la intención de enseñar."),
   ("Creer que leer literatura solo sirve para pasar el rato.", "Se olvida su valor cultural.", "También sirve para conocer el mundo y tradiciones.")],
  ([E("¿Qué género se escribe en versos: el poema o la novela?", "El poema", "Los versos son las líneas de un poema."),
    E("¿Qué género termina con una moraleja?", "La fábula", "La moraleja es su enseñanza final."),
    E("¿Qué rasgos tiene una historieta: viñetas y globos de diálogo o capítulos?", "Viñetas y globos de diálogo", "Son sus elementos propios.")],
   [E(f"Lee: «{MITO}» ¿Qué explica este mito: el origen del día y la noche o el origen de un río?", "El origen del día y la noche", "El texto dice «Así nacieron el día y la noche»."),
    E("Quieres conocer cómo vivían las personas de otra época. ¿Qué te aporta la literatura: costumbres y lugares de otros tiempos o ningún dato?", "Costumbres y lugares de otros tiempos", "Las historias muestran formas de vida."),
    E(f"Lee: «{FAB}» ¿Cuál es el animal protagonista?", "Un gallo", "El texto comienza con él.")],
   [E(f"Lee: «{LEY}» ¿Qué hacen los vecinos cuando cae la primera nieve?", "Dejan un farol de colores junto a la orilla", "Está en la segunda oración."),
    arith("Una novela de 240 páginas tiene 12 capítulos de igual largo. ¿Cuántas páginas tiene cada capítulo?", "240//12", "Se reparten las páginas en partes iguales."),
    E(f"¿Cuántos versos tiene este poema: «{POEMA}»? (Las barras separan los versos.)", str(POEMA.count("/") + 1), "Se cuentan los versos separados por barras.")],
   [E(f"Lee: «{FOLK}» ¿Qué enseña sobre compartir: que compartir hace que haya para todos o que conviene guardar todo para uno?", "Que compartir hace que haya para todos", "La olla solo daba sopa si se compartía."),
    E(f"En esta leyenda: «{LEY}» ¿qué parte es fantástica: que la laguna se formó con lágrimas o que cae nieve?", "Que la laguna se formó con lágrimas", "Las nevadas son reales; la laguna formada de lágrimas no.")],
   [arith("Una biblioteca tiene 150 libros: 60 novelas, 40 de poemas y el resto cuentos. ¿Cuántos son cuentos?", "150-60-40", "Se restan las novelas y los libros de poemas del total."),
    arith("Lees una fábula de lunes a viernes y una leyenda el sábado. ¿Cuántas lecturas haces en 4 semanas?", "(5+1)*4", "Cada semana hay 6 lecturas, por 4 semanas.")]),
  [E("En la biblioteca de tu sala hay estantes llamados «Poemas», «Leyendas» e «Historietas». Quieres leer algo con globos de diálogo y dibujos. ¿A qué estante vas?", "Historietas", "Ese género usa viñetas y globos.")],
  [E("¿Qué género explica el origen del mundo o de un fenómeno: el mito o la novela?", "El mito", "Cuenta cómo comenzó algo."),
   E("¿Un cuento folclórico viene de la tradición oral?", "Sí", "Se contó de boca en boca."),
   E("¿La novela se divide en capítulos o en versos?", "En capítulos", "Los versos son propios del poema.")],
  ("Lee estos tres textos y escribe para cada uno su género y una pista: A) «Capítulo 2. Cuando amaneció, Elisa ya había terminado de preparar la mochila.» B) «Viñeta 1: un gato mira por la ventana. Globo de pensamiento: «Quiero salir».» C) «Moraleja: quien comparte, nunca queda solo.» Luego explica en una oración para qué sirve leer literatura.",
   "A) Novela; pista: la palabra «Capítulo». B) Historieta; pista: viñeta y globo de pensamiento. C) Fábula; pista: moraleja. Leer literatura sirve para conocer mundos nuevos, imaginar y valorar historias de nuestra cultura.",
   ["reconoce los tres géneros", "da una pista textual por cada uno", "explica la utilidad de leer literatura"], ["tres respuestas con pista", "oración explicativa"], ["decidir el género sin pista", "decir que no sirve para nada"], "Subraya en cada texto la palabra que usaste como pista."),
  "Pregunta a alguien de tu casa qué cuento o leyenda recuerda de cuando era niño y cuenta de qué género sería.",
  "Haz una lista de siete géneros literarios con una frase que diga cómo reconocer cada uno.")

L(OA3, 2,
  MAT,
  "Aprenderé a modelar una lectura literaria pensando en voz alta: qué me enseña el texto del mundo, qué imagino y por qué importa para una comunidad.",
  ["Conozco los géneros literarios.", "Releo para comprender mejor."],
  ["Un lector de literatura se hace tres preguntas mientras lee. Primera: ¿qué aprendo del mundo? Una leyenda puede mostrar costumbres de un lugar; un mito, cómo las personas explicaban fenómenos de la naturaleza. Segunda: ¿qué imagino? Cierra los ojos y piensa en la escena. Tercera: ¿por qué esta historia importa a quienes la cuentan?",
   "Modelar la lectura es decir en voz alta esas ideas. Por ejemplo: «Aquí los vecinos dejan un farol; parece que cuidan a los suyos». «Me imagino la nieve cubriendo la laguna». «Esta historia se cuenta para recordar a quien se pierde». Estas frases usan evidencia del texto.",
   "El valor social y cultural de la literatura está en que sus historias reúnen a las personas: se cuentan en familia, en la escuela, en fiestas. Cuando una comunidad conserva sus relatos, conserva sus valores y su forma de ver el mundo."],
  [("valor cultural", "importancia que tiene algo para la cultura de un pueblo"), ("comunidad", "grupo de personas que comparten un lugar o una tradición"), ("imaginar", "formar imágenes en la mente a partir de lo leído"), ("costumbre", "forma de actuar que se repite en un grupo")],
  [("Qué aprendo del mundo", f"Lee: «{LEY}» ¿Qué aprendes de la comunidad?",
    ["Veo que los vecinos dejan un farol cuando cae la primera nieve.", "Eso muestra una costumbre.", "Aprendo que se preocupan por quien puede perderse."],
    "Que la comunidad cuida a quien puede perderse"),
   ("Imaginar la escena", f"Lee: «{MITO}» ¿Qué imagen te haces de la Tortuga Gigante?",
    ["Leo que carga la luz en su caparazón.", "Imagino un caparazón enorme que brilla.", "Veo que la luz sube y baja cuando respira."],
    "Una tortuga enorme cuyo caparazón brilla y cambia al respirar")],
  [("Contar la historia sin decir qué se aprende de ella.", "Se queda en lo que pasó.", "Pregúntate también qué enseña sobre el mundo."),
   ("Inventar costumbres que el texto no menciona.", "Se confunde imaginar con inventar datos.", "Apóyate en lo que el texto dice.")],
  ([E(f"Lee: «{MITO}» ¿Qué cargaba la Tortuga Gigante en su caparazón?", "La luz", "El texto lo dice en la segunda oración."),
    E("«Aquí los vecinos dejan un farol» ¿es una frase para decir qué aprendo del mundo o una pregunta?", "Una frase de lo que aprendo", "Es una observación basada en el texto."),
    E("Los relatos se cuentan en familia y en la escuela. ¿Eso muestra el valor cultural o ningún valor?", "El valor cultural", "Reúnen a la comunidad.")],
   [E(f"Con este texto: «{MITO}» ¿qué explicaba este mito a las personas: cómo nació el día y la noche o cómo se hace una olla?", "Cómo nacieron el día y la noche", "Es la explicación que ofrece."),
    E(f"En esta fábula: «{FAB}» ¿qué descubre el gallo cuando se enferma?", "Que el sol sale aunque él no cante", "El texto dice que el sol salió igual."),
    E("Un lector dice: «Me imagino la nieve cubriendo la laguna». ¿Está imaginando a partir del texto de la leyenda de Calderilla?", "Sí", "La nevada aparece en el texto.")],
   [E(f"Lee: «{FAB}» ¿Cuál es la moraleja, según el texto?", "No te creas dueño de lo que no depende de ti", "Aparece al final."),
    arith("Una comunidad cuenta una leyenda en 4 fiestas al año durante 3 años. ¿Cuántas veces se contó?", "4*3", "Se multiplican las fiestas por los años."),
    E(f"Lee: «{FOLK}» ¿Qué le pasó a la olla cuando la anciana quiso guardarla para ella sola?", "Quedó vacía para siempre", "Es la última parte del texto.")],
   [E(f"Según la leyenda: «{LEY}» ¿qué crees que valora esa comunidad: cuidar a quien se pierde o ganar rebaños?", "Cuidar a quien se pierde", "La costumbre del farol lo muestra."),
    E("Un lector dice: «Esta historia importa porque los abuelos la cuentan a los niños». ¿Habla del valor social o de la ortografía?", "Del valor social", "Habla de cómo se transmite entre personas.")],
   [E(f"Compara: «{FAB}» y «{MITO}». ¿Cuál de los dos termina con una enseñanza explícita (moraleja)?", "La fábula del gallo", "El mito explica el origen del día y la noche; la fábula tiene moraleja."),
    E("Si una historia explica una costumbre del pueblo y nadie sabe quién la inventó, ¿puede venir de la tradición oral?", "Sí", "La tradición oral no tiene autor conocido.")]),
  [E("Un compañero te cuenta una leyenda que su abuelo le contó sobre un cerro. Al escucharla, te das cuenta de que enseña a respetar el lugar. ¿Qué aprendiste con esa leyenda: algo sobre los valores de esa comunidad o ningún dato?", "Algo sobre los valores de esa comunidad", "Las leyendas transmiten valores.")],
  [E("¿Cuál es una pregunta que se hace un lector de literatura: ¿qué aprendo del mundo? o ¿cuánto pesa el libro?", "¿Qué aprendo del mundo?", "Es una pregunta sobre el sentido del texto."),
   E("¿Imaginar la escena ayuda a comprender?", "Sí", "Ver la escena en la mente da sentido a las palabras."),
   E("¿Una costumbre es algo que se repite en un grupo o algo que ocurre una sola vez?", "Algo que se repite en un grupo", "Esa es su definición.")],
  ("Lee: «Cuentan en la aldea de Piedra Larga que los abuelos plantan un árbol cuando nace cada niño. Así, cuando el niño crece, tiene su árbol para cuidar.» Piensa en voz alta y escribe tres frases: 1) algo que aprendes del mundo, 2) algo que imaginas, 3) por qué crees que esa historia importa a la aldea.",
   "1) Aprendo que en esa aldea se plantan árboles para los recién nacidos. 2) Me imagino un bosque donde cada árbol tiene el nombre de un niño. 3) Importa porque enseña a cuidar la naturaleza y a la familia.",
   ["usa evidencia del texto en cada frase", "imagina sin contradecir el texto", "relaciona con la comunidad"], ["tres frases escritas"], ["inventar costumbres no dichas", "no explicar la importancia"], "Revisa que cada frase se apoye en algo que dice el texto."),
  "Cuenta una historia que te hayan contado en tu familia y explica qué enseña.",
  "Escribe un mito corto original sobre el origen de la lluvia, en cuatro oraciones.")

L(OA3, 3,
  MAT,
  "Aprenderé a elegir evidencias del texto para justificar a qué género pertenece y qué aporta su lectura.",
  ["Reconozco los géneros literarios.", "Subrayo pistas en un texto."],
  ["Para justificar que un texto es de cierto género no basta con decirlo: hay que mostrar evidencia. La evidencia es una palabra o frase del texto que sirve de pista. «Capítulo» es evidencia de novela; «viñeta», de historieta; «moraleja», de fábula; «Había una vez», de cuento tradicional; los versos, de poema.",
   "También hay pistas de contenido. Si el texto cuenta cómo se formó un lugar y mezcla algo real con algo fantástico, es una leyenda. Si explica el origen del mundo o de un fenómeno con seres extraordinarios, es un mito. Si los protagonistas son animales con conductas humanas y hay una enseñanza, es una fábula.",
   "Un buen lector selecciona la pista más fuerte y la explica: «Es una fábula porque los protagonistas son animales que hablan y termina con una moraleja». Usa siempre «porque» y cita la parte del texto que lo prueba."],
  [("evidencia", "parte del texto que sirve de prueba"), ("pista", "palabra o frase que ayuda a descubrir algo"), ("justificar", "explicar con razones por qué algo es así"), ("rasgo", "característica propia de algo")],
  [("Justificar un género", f"Lee: «{FAB}» ¿Es fábula o mito? Justifica.",
    ["Veo que el protagonista es un animal que habla.", "Veo la palabra «Moraleja» al final.", "Es una fábula porque tiene animal protagonista y moraleja."],
    "Fábula, porque el protagonista es un animal y hay moraleja"),
   ("Elegir la mejor pista", "Texto: «Capítulo 3. Los pasos en la escalera». ¿Qué pista prueba que es parte de una novela?",
    ["La palabra «Capítulo» marca una división.", "Un poema no se divide así.", "La mejor pista es «Capítulo 3»."],
    "La palabra «Capítulo»")],
  [("Justificar solo con «porque sí».", "No se señala qué parte del texto lo prueba.", "Cita la pista y explica."),
   ("Elegir una pista que no distingue el género.", "Por ejemplo, decir que un cuento es de ficción.", "Elige una pista propia de ese género.")],
  ([E(f"Lee: «{NOVELA}» ¿Qué palabra del texto es pista de que es una novela?", "Capítulo", "Las novelas se dividen en capítulos."),
    E(f"Lee: «{HIST}» ¿Qué palabra es pista de historieta?", "Viñeta", "Las historietas se organizan en viñetas."),
    E("¿«Moraleja» es pista de qué género: fábula o historieta?", "Fábula", "La moraleja cierra las fábulas.")],
   [E(f"¿Cuál es la pista que prueba que «{POEMA}» es un poema: los versos separados por barras o la palabra «moraleja»?", "Los versos separados por barras", "El poema se escribe en versos."),
    E(f"Lee: «{MITO}» ¿Es mito o fábula? Responde con una palabra.", "Mito", "Explica el origen del día y la noche."),
    E("Un texto dice: «Había una vez un rey que quería saber qué era la felicidad». ¿Qué frase es pista de cuento tradicional?", "Había una vez", "Es una fórmula típica de inicio.")],
   [E(f"Lee: «{LEY}» ¿Cuál es la pista de contenido de que es una leyenda: explica cómo se formó una laguna o tiene capítulos?", "Explica cómo se formó una laguna", "Las leyendas explican lugares."),
    E(f"En la fábula: «{FAB}» ¿cuántas veces aparece la palabra «gallo»? Cuenta cada vez que se escribe.", str(FAB.count("gallo") + FAB.count("Gallo")), "Se cuenta cada aparición de la palabra en el texto."),
    arith("Un libro de poemas tiene 8 poemas de 12 versos cada uno. ¿Cuántos versos tiene en total?", "8*12", "Se multiplica el número de poemas por los versos de cada uno.")],
   [E("Un compañero dice: «Es una novela porque tiene personajes». ¿La pista es suficiente para distinguir la novela de otros géneros?", "No", "También los cuentos y las leyendas tienen personajes."),
    E(f"Lee: «{FOLK}» Si alguien dice que es una fábula, ¿cuál es la razón para dudarlo: no tiene animales protagonistas o tiene una olla?", "No tiene animales protagonistas", "Sus personajes son una anciana y una olla, no animales.")],
   [E("Un texto tiene tres versos, un animal que habla y ninguna moraleja. ¿Cuál es la pista más fuerte de poema: los versos o el animal que habla?", "Los versos", "Un animal que habla puede aparecer en varios géneros."),
    E("Completa con la mejor justificación: «Es una historieta porque ___». Elige: «tiene viñetas y globos de diálogo» o «es entretenida».", "Tiene viñetas y globos de diálogo", "Cita una característica propia del género.")]),
  [E(f"En un concurso, debes decidir de qué género es: «{LEY}». Escribes «leyenda». ¿Qué pista citas: «pueblo imaginario» o «la laguna se formó con las lágrimas»?", "La laguna se formó con las lágrimas", "Explica el origen de un lugar con algo fantástico.")],
  [E("¿Qué es la evidencia de un texto: una parte que sirve de prueba o una opinión?", "Una parte que sirve de prueba", "Se puede señalar."),
   E("¿Qué palabra usas para justificar una respuesta: «porque» o «quizás»?", "Porque", "Introduce la razón."),
   E("¿«Capítulo» es pista de novela o de poema?", "De novela", "Los capítulos dividen una novela.")],
  ("Lee estos fragmentos y escribe género y evidencia para cada uno: A) «Viñeta 2: la niña grita desde el árbol. Onomatopeya: ¡CRAC!» B) «Moraleja: quien tiene paciencia, alcanza lo que desea.» C) «Cuentan que al principio el mundo era de agua y que el Primer Pájaro trajo la tierra en su pico.» D) «Capítulo 5. El regreso.»",
   "A) Historieta; evidencia: viñeta y onomatopeya. B) Fábula; evidencia: moraleja. C) Mito; evidencia: explica el origen del mundo con un ser extraordinario. D) Novela; evidencia: capítulo.",
   ["acierta los géneros", "cita evidencia en cada caso", "usa «porque»"], ["cuatro respuestas con evidencia"], ["justificar sin citar", "pista que no distingue"], "Subraya en cada fragmento la palabra o frase que usaste como evidencia."),
  "Busca en un libro de tu casa una pista que muestre el género y copia la frase.",
  "Escribe tres frases de inicio de textos de distintos géneros y pide a alguien que adivine cuáles son.")

L(OA3, 4,
  MAT,
  "Aprenderé a comparar dos textos literarios de géneros o autores distintos: qué tienen en común, en qué se diferencian y qué enseña cada uno.",
  ["Reconozco los géneros.", "Cito evidencias."],
  ["Comparar es buscar semejanzas y diferencias entre dos textos con criterios. Algunos criterios útiles son: el género, los personajes, el lugar, lo que explica o enseña, y el tono (alegre, serio, misterioso). Comparar un cuento folclórico con uno de autor permite ver que ambos cuentan historias, pero que uno viene de la tradición oral y el otro tiene un autor conocido.",
   "Una fábula y una leyenda pueden compartir que tienen una enseñanza implícita, pero se diferencian en que la fábula usa animales y una moraleja, y la leyenda explica algo de un lugar. Un poema y una novela comparten que expresan emociones, pero uno usa versos y el otro capítulos.",
   "Para comparar bien, ordena la información en una tabla de dos columnas y escribe al menos una semejanza y una diferencia por criterio. Al final, concluye: ¿cuál te dejó más ideas?, ¿por qué? Tu conclusión debe tener una razón basada en el texto."],
  [("semejanza", "característica que dos cosas tienen en común"), ("diferencia", "característica en que dos cosas no coinciden"), ("criterio", "aspecto usado para comparar"), ("conclusión", "idea final a la que se llega con razones")],
  [("Comparar con criterios", f"Compara «{FAB}» y «{MITO}» según si tienen moraleja.",
    ["La fábula del gallo tiene moraleja escrita.", "El mito no tiene moraleja, explica un origen.", "Diferencia: solo la fábula cierra con una enseñanza."],
    "La fábula tiene moraleja y el mito no"),
   ("Encontrar semejanzas", f"Compara «{LEY}» y «{MITO}». ¿Qué tienen en común?",
    ["Ambos explican algo: una laguna y el día y la noche.", "Ambos incluyen algo fantástico: lágrimas que forman una laguna y una tortuga gigante que carga la luz.", "Semejanza: explican el origen de algo con elementos fantásticos."],
    "Los dos explican el origen de algo con elementos fantásticos")],
  [("Decir solo que son «distintos» sin criterio.", "No se señala en qué.", "Nombra el criterio: género, personajes, enseñanza."),
   ("Comparar un texto con lo que uno hubiera escrito.", "Se confunde comparar con opinar.", "Compara lo que dicen los dos textos.")],
  ([E(f"Lee: «{FAB}» y «{FOLK}». ¿Cuál de los dos tiene un animal como protagonista?", "La fábula del gallo", "El otro texto tiene a una anciana y una olla."),
    E("Comparar es buscar semejanzas y diferencias con criterios. ¿Verdadero o falso?", "Verdadero", "Esa es su definición."),
    E("Un criterio de comparación es «el género». ¿Es un criterio válido?", "Sí", "Permite ver qué tipo de texto es cada uno.")],
   [E(f"Compara «{MITO}» y «{LEY}». ¿Cuál menciona a un pueblo y a sus vecinos?", "La leyenda", "La leyenda nombra el pueblo y a los vecinos."),
    E(f"Lee: «{FOLK}» y «{POEMA}». ¿Cuál se divide en versos?", "El poema", "El otro es un texto en prosa."),
    E("Un cuento de autor se diferencia de un cuento folclórico en que el de autor ____. Elige: «tiene un autor conocido» o «no tiene personajes».", "Tiene un autor conocido", "El folclórico es anónimo, de tradición oral.")],
   [arith("Una tabla compara 5 criterios. Para cada uno escribes 1 semejanza y 1 diferencia. ¿Cuántas anotaciones escribes en total?", "5*2", "Se anotan dos por cada criterio."),
    E(f"Compara «{FAB}» y «{FOLK}». ¿Qué tienen en común: ambos dejan una enseñanza o ambos tienen versos?", "Ambos dejan una enseñanza", "El gallo con moraleja; la olla enseña a compartir."),
    E(f"Compara «{MITO}» y «{FAB}». ¿Cuál explica un fenómeno de la naturaleza?", "El mito", "Explica el día y la noche.")],
   [E("Dos lectoras comparan. Ana dice: «La fábula es mejor porque sí». Bea dice: «La fábula es más clara porque trae una moraleja escrita». ¿Quién usa un criterio observable?", "Bea", "Señala una característica del texto."),
    E("¿Qué hace falta para que una conclusión de comparación sea válida: una razón basada en el texto o repetir el título?", "Una razón basada en el texto", "Debe apoyarse en evidencia.")],
   [E(f"Compara «{LEY}» y «{FOLK}». Elige la semejanza: «ambas tienen animales que hablan» o «ambas muestran valores de ayuda y generosidad entre las personas»?", "Ambas muestran valores de ayuda y generosidad entre las personas", "Los vecinos cuidan a la pastora; la olla da sopa si se comparte."),
    arith("En una tabla escribes 3 semejanzas y 4 diferencias entre dos textos. ¿Cuántas diferencias más que semejanzas escribiste?", "4-3", "Se resta la cantidad de semejanzas a la de diferencias.")]),
  [E("En clase leen una fábula y una leyenda. Un compañero dice que se parecen porque las dos enseñan algo sobre cómo comportarse. ¿Es una semejanza posible?", "Sí", "Ambas pueden dejar una enseñanza.")],
  [E("¿Una tabla de dos columnas sirve para comparar?", "Sí", "Ordena semejanzas y diferencias."),
   E("¿Qué diferencia a un cuento de autor de uno folclórico: el autor conocido o el título?", "El autor conocido", "El folclórico es anónimo."),
   E("¿Qué debe tener una conclusión: una razón o un título?", "Una razón", "Debe estar justificada.")],
  ("Compara estos dos textos. Texto 1: «Una zorra le dijo al río: —Me gustas porque nunca te quedas quieto. Moraleja: lo que se mueve no se estanca.» Texto 2: «Dicen que la montaña tiene un lago escondido porque un gigante lloró allí. Los vecinos no suben en invierno para respetarlo.» Completa una tabla con tres criterios (género, protagonistas, qué enseña o explica) y escribe una conclusión con una razón.",
   "Género: 1 fábula, 2 leyenda. Protagonistas: 1 una zorra y un río, 2 un gigante y los vecinos. Qué enseña o explica: 1 que moverse evita estancarse, 2 el origen de un lago y la costumbre de respetarlo. Conclusión: me gustó más el texto 2 porque explica una costumbre del lugar.",
   ["usa tres criterios", "señala semejanzas y diferencias", "concluye con una razón"], ["tabla completada", "conclusión escrita"], ["comparar sin criterios", "conclusión sin razón"], "Subraya en cada texto la frase que sustenta cada fila de tu tabla."),
  "Compara dos cuentos que conozcas y anota dos semejanzas y dos diferencias.",
  "Elige una fábula y una leyenda conocidas y compara qué valores transmiten.")

L(OA3, 5,
  MAT,
  "Aprenderé a producir una recomendación de lectura propia: presentar una obra, decir de qué género es y justificar por qué vale la pena leerla.",
  ["Reconozco géneros.", "Comparo textos con criterios."],
  ["Recomendar una obra es invitar a otra persona a leerla. Una buena recomendación tiene cuatro partes: el título y el género; de qué trata, sin contar el final; una razón para leerla; y a quién se la recomiendas. La razón es lo más importante, porque convence con motivos del texto.",
   "Las razones pueden ser: lo que aprendes del mundo, lo que imaginas, la emoción que provoca o el valor cultural. Por ejemplo: «Te recomiendo esta leyenda porque cuenta cómo se formó una laguna y muestra cómo una comunidad cuida a los suyos». Observa que usa evidencia y no solo «me gustó».",
   "Para escribirla, usa verbos como «recomiendo», «trata de», «me enseñó» y conectores como «porque» y «además». Revisa que no cuentes el final, que nombres el género y que el texto sea claro para quien lo lea."],
  [("recomendación", "texto que invita a leer una obra y explica por qué"), ("argumento", "razón que apoya una opinión"), ("sinopsis", "resumen breve de lo que trata una obra"), ("destinatario", "persona a quien se dirige un mensaje")],
  [("Identificar las partes", "«Te recomiendo la fábula del gallo orgulloso porque enseña a no creerse dueño de todo. Es ideal para quienes les gustan las historias cortas con animales.» ¿Cuáles son las partes?",
    ["Título y género: la fábula del gallo orgulloso.", "Razón: porque enseña a no creerse dueño de todo.", "Destinatario: quienes les gustan las historias cortas con animales."],
    "Título y género, razón y destinatario"),
   ("Mejorar una razón", "Una recomendación dice: «Léelo porque está bien». ¿Cómo la mejoras?",
    ["«Está bien» no da motivo.", "Pienso qué me enseñó: cómo se forma una laguna.", "Escribo: «Léelo porque explica cómo se formó una laguna y muestra una costumbre»."],
    "Se agrega una razón con un dato del texto")],
  [("Contar el final de la obra.", "Se cree que así se convence.", "Invita sin revelar el final."),
   ("Dar como razón solo «me gustó».", "Falta un motivo observable.", "Explica qué aprendiste, imaginaste o sentiste.")],
  ([E("¿Debe una recomendación contar el final de la obra?", "No", "Quita el interés de leerla."),
    E("¿Qué es la parte más importante de una recomendación: la razón o el color de la portada?", "La razón", "Es lo que convence."),
    E("En «Te la recomiendo a quienes les gustan los misterios», ¿qué parte es: título, destinatario o razón?", "Destinatario", "Dice a quién se recomienda.")],
   [E("Elige la mejor razón para recomendar una leyenda: «porque explica cómo nació un lugar» o «porque es corta»?", "Porque explica cómo nació un lugar", "Es un motivo del contenido."),
    E("¿Cuál conector sirve para dar una razón: «porque» o «aunque»?", "Porque", "Introduce el motivo."),
    E("Una recomendación dice el género de la obra. ¿Es una de sus partes?", "Sí", "El género es parte del título y género.")],
   [arith("Una recomendación tiene 4 partes y escribes 2 oraciones por parte. ¿Cuántas oraciones escribes?", "4*2", "Se multiplican las partes por las oraciones de cada una."),
    E("Completa con una razón: «Te recomiendo este poema porque ___». Elige: «sus versos me hicieron imaginar el viento» o «es un texto».", "Sus versos me hicieron imaginar el viento", "Explica lo que provoca el poema."),
    E("¿Cuál invita sin revelar el final: «Descubrirás qué pasó con la pastora» o «La pastora muere»?", "«Descubrirás qué pasó con la pastora»", "No cuenta lo que ocurre al final.")],
   [E("Dos recomendaciones: A dice «Es de miedo y me gustó». B dice «Es de misterio y enseña a no juzgar sin pruebas». ¿Cuál tiene un argumento más fuerte?", "B", "Da una razón basada en lo que enseña."),
    E("Quieres recomendar una novela a un compañero de primero básico. ¿Conviene elegir una con muchos capítulos o una breve con dibujos?", "Una breve con dibujos", "Se adapta al destinatario.")],
   [E("Recomendación: «Te recomiendo la leyenda de Calderilla, que cuenta cómo nació una laguna, porque muestra cómo una comunidad cuida a los suyos». ¿Qué parte falta: el destinatario o la razón?", "El destinatario", "No dice a quién se la recomienda."),
    arith("Escribes tres recomendaciones de 5 oraciones cada una. ¿Cuántas oraciones escribiste?", "3*5", "Se multiplica por la cantidad de recomendaciones.")]),
  [E("Para el cartel de la feria del libro del colegio escribes una recomendación. ¿Qué parte NO debe llevar: el final de la historia, la razón o el destinatario?", "El final de la historia", "Revelarlo quita el interés de leer la obra.")],
  [E("¿Cuántas partes tiene la recomendación que se explicó: cuatro o diez?", "Cuatro", "Título y género, sinopsis, razón y destinatario."),
   E("¿La razón debe basarse en el texto o en el precio del libro?", "En el texto", "Debe ser un motivo de la obra."),
   E("¿«Porque» introduce una razón?", "Sí", "Es el conector más usado.")],
  ("Elige uno de estos tres textos y escribe una recomendación de cuatro oraciones: A) La fábula del gallo: «Un gallo orgulloso cree que el sol sale por su canto; un día enferma y el sol sale igual. Moraleja: no te creas dueño de lo que no depende de ti.» B) El mito de la Tortuga Gigante: «La Tortuga carga la luz en su caparazón; cuando respira, nacen el día y la noche.» C) La leyenda de Calderilla: «Una laguna nace de las lágrimas de una pastora; los vecinos dejan un farol de colores cuando cae la primera nieve.»",
   "Te recomiendo la fábula del gallo orgulloso. Trata de un gallo que cree que su canto hace salir el sol. Te la recomiendo porque enseña a no creerse dueño de todo. Es ideal para quienes les gustan las historias breves con animales.",
   ["incluye título y género", "da una razón con evidencia", "indica a quién la recomienda", "no cuenta el final"], ["recomendación de cuatro oraciones"], ["razón solo «me gustó»", "contar el final"], "Subraya la razón y comprueba que se apoye en algo que dice el texto."),
  "Recomienda oralmente un libro que hayas leído a alguien de tu casa y pídele que repita por qué lo leería.",
  "Escribe una recomendación para un destinatario distinto (un niño de primero básico) y compara.")

L(OA3, 6,
  MAT,
  "Aprenderé a revisar mi recomendación de lectura para que sea clara, convincente y adecuada a quien la va a leer.",
  ["Sé escribir una recomendación con cuatro partes.", "Reviso ortografía y puntuación."],
  ["Revisar una recomendación es leerla como si fueras otra persona que no conoce la obra. Pregúntate: ¿se entiende de qué trata?, ¿está la razón?, ¿sé para quién es?, ¿hay errores de ortografía o de puntuación? Si algo no queda claro, mejora esa parte.",
   "La audiencia cambia el modo de escribir. Para niños pequeños, usa frases cortas y palabras sencillas. Para compañeros de tu edad, puedes dar razones más desarrolladas. Para un adulto, puedes explicar el valor cultural de la obra. Piensa en quién leerá y ajusta.",
   "Una lista de revisión ayuda: 1) nombré el título y el género; 2) expliqué de qué trata sin contar el final; 3) di una razón con evidencia; 4) indiqué el destinatario; 5) revisé ortografía y puntuación. Cada punto cumplido es un paso hacia una recomendación convincente."],
  [("revisar", "leer de nuevo para mejorar un texto"), ("audiencia", "personas que leerán el texto"), ("lista de revisión", "conjunto de preguntas para comprobar un texto"), ("convincente", "que logra que otra persona se interese")],
  [("Revisar con lista", "«Te recomiendo la leyenda porque esta bn. Es para todos.» Revisa con la lista.",
    ["Falta el título y el género completos.", "La razón «está bien» no es evidencia.", "Hay un error de ortografía: «bn»; y no dice de qué trata."],
    "Faltan título, sinopsis y una razón con evidencia; hay error de ortografía"),
   ("Adaptar a la audiencia", "Debes recomendar el mito de la Tortuga Gigante a un niño de primero básico. ¿Cómo lo escribes?",
    ["Uso frases cortas y palabras simples.", "Explico lo principal: la tortuga lleva la luz.", "Escribo: «Lee este cuento: una tortuga gigante lleva la luz y así nacen el día y la noche»."],
    "Una versión con frases cortas y palabras simples")],
  [("Revisar solo la ortografía.", "Se cree que corregir faltas basta.", "Revisa también la razón y el destinatario."),
   ("Usar el mismo texto para todos los lectores.", "No se piensa en la audiencia.", "Adapta palabras y frases a quien lee.")],
  ([E("En una revisión, ¿es importante preguntarse si la razón está presente?", "Sí", "Sin razón no convence."),
    E("Si escribes para un niño pequeño, ¿conviene usar frases cortas o párrafos muy largos?", "Frases cortas", "Se entienden mejor."),
    E("¿«bn» en lugar de «bien» es un error de ortografía o de contenido?", "De ortografía", "Faltan letras de la palabra.")],
   [E("Una recomendación dice «Léela porque es muy buena». ¿Qué le falta a la razón: evidencia o un título más largo?", "Evidencia", "No explica qué la hace buena."),
    E("Ves que tu recomendación cuenta el final. ¿Qué haces al revisar: lo quitas o lo dejas?", "Lo quito", "Una recomendación no revela el final."),
    E("Ves que el texto no dice a quién se recomienda la obra. ¿Qué punto de la lista incumple: el destinatario o la ortografía?", "El destinatario", "No indica para quién es la recomendación.")],
   [arith("Tu lista de revisión tiene 5 puntos y cumples 3. ¿Cuántos puntos te faltan?", "5-3", "Se resta lo cumplido del total."),
    E("Recomendación: «Este poema habla del viento. Es para quienes les gusta imaginar». ¿Qué parte falta: la razón con evidencia o el destinatario?", "La razón con evidencia", "No dice qué versos o ideas lo hacen valioso."),
    E("¿Cuál frase es más adecuada para un niño de 6 años: «Una tortuga lleva la luz y así hay día y noche» o «El relato cosmogónico presenta un fenómeno astronómico»?", "«Una tortuga lleva la luz y así hay día y noche»", "Usa palabras sencillas.")],
   [E("Un compañero lee tu recomendación y dice que no entendió de qué trata. ¿Qué parte debes mejorar: la sinopsis o el título?", "La sinopsis", "Ahí se explica de qué trata."),
    E("Dos recomendaciones tienen la misma razón, pero una está dirigida a «cualquier persona» y la otra a «quienes aman los animales». ¿Cuál tiene un destinatario más claro?", "La que dice «quienes aman los animales»", "Precisa a quién se recomienda.")],
   [arith("Revisas una recomendación de 60 palabras y quitas 12 repetidas y 8 que cuentan el final. ¿Cuántas palabras quedan?", "60-12-8", "Se restan las palabras eliminadas."),
    arith("Tu lista de revisión tiene 5 puntos. Una recomendación cumple solo el de ortografía. ¿Cuántos puntos incumple?", "5-1", "Se resta lo cumplido del total.")]),
  [E("Una compañera te pide revisar su recomendación del cuento. Falta la razón. ¿Qué le sugieres: agregar una razón con un dato del cuento o cambiar la letra?", "Agregar una razón con un dato del cuento", "La razón es lo que convence.")],
  [E("¿A quién debes pensar al revisar: al lector o solo a ti?", "Al lector", "Es la audiencia."),
   E("¿Una lista de revisión ayuda a comprobar un texto?", "Sí", "Ordena las preguntas."),
   E("¿Debes revisar solo la ortografía?", "No", "También el contenido y la audiencia.")],
  ("Revisa esta recomendación y escríbela de nuevo mejor: «Te recomiendo la historieta del globo porque es buena. Un niño corre. Al final lo consigue y se pone feliz. Léela.» Usa la lista de cinco puntos, indica cuáles no cumple y escribe la versión final para un compañero de tu curso.",
   "No cumple: no explica de qué trata (solo dice «Un niño corre»), la razón es débil, no dice el destinatario y cuenta el final. Versión: «Te recomiendo la historieta del globo rojo porque, con pocas viñetas, muestra cómo un niño busca soluciones. Es para quienes disfrutan los cómics cortos y divertidos.»",
   ["detecta los puntos incumplidos", "quita el final", "escribe una versión mejorada"], ["lista marcada", "versión final"], ["dejar el final", "no mencionar el destinatario"], "Lee tu versión final en voz alta y pregunta a otra persona si le dieron ganas de leer la historieta."),
  "Pide a alguien de tu casa que lea tu recomendación y diga si le dieron ganas de leer la obra.",
  "Escribe una recomendación para dos audiencias distintas y explica qué cambiaste.")
